//! The PostgreSQL repository of posts against a real database
//! migrated with the application's migrations: round trip, optimistic
//! locking and cursor pages. Generated by
//! `forge generate scaffold`.
//!
//! PostgreSQL tests run as the runtime role an application serves with
//! (`forge::db::testing::RlsTestDatabase`: a fresh migration role applies
//! the migrations, a fresh `NOSUPERUSER NOBYPASSRLS` role with data
//! privileges only runs the queries; both are dropped afterwards), so
//! row-level security applies to them as in production. They need
//! `FORGE_TEST_DATABASE_URL` (a superuser, as in the generated Compose
//! service and CI) and are ignored by default:
//! `cargo test -- --include-ignored`.

use std::error::Error;

use app::application::ports::post_repository::{PostRepository, PostStoreError};
use app::domain::entities::post::{Post, PostAttributes};
use app::infrastructure::database::posts::PgPostRepository;
use forge::core::Version;
use forge::db::PgDatabase;
use forge::db::testing::RlsTestDatabase;

type TestResult = Result<(), Box<dyn Error>>;

static MIGRATOR: sqlx::migrate::Migrator = sqlx::migrate!();

fn attributes() -> Result<PostAttributes, Box<dyn Error>> {
    Ok(PostAttributes {
        title: "Example title".to_owned(),
        body: "Example body".to_owned(),
        published: true,
    })
}

async fn exercise(database: &PgDatabase) -> TestResult {
    let repository = PgPostRepository::new(database.clone());
    let post = Post::new(attributes()?)?;

    repository.insert(&post).await?;
    assert_eq!(repository.find(post.id()).await?, Some(post.clone()));

    let version = repository.update(&post).await?;
    assert_eq!(version.get(), 2);
    assert!(matches!(
        repository.update(&post).await,
        Err(PostStoreError::Conflict)
    ));
    assert!(matches!(
        repository.delete(post.id(), Version::INITIAL).await,
        Err(PostStoreError::Conflict)
    ));
    let stored = repository.find(post.id()).await?;
    assert_eq!(stored.map(|stored| stored.version()), Some(version));

    for _ in 0..2 {
        repository.insert(&Post::new(attributes()?)?).await?;
    }
    let first = repository.page(None, 2).await?;
    assert_eq!(first.posts.len(), 2);
    assert_eq!(first.posts[0].id(), post.id());
    assert!(first.next.is_some());
    let rest = repository.page(first.next, 2).await?;
    assert_eq!(rest.posts.len(), 1);
    assert!(rest.next.is_none());

    repository.delete(post.id(), version).await?;
    assert_eq!(repository.find(post.id()).await?, None);
    Ok(())
}

/// PostgreSQL's `42501`, also raised for a row that violates a row-level
/// security policy.
fn insufficient_privilege<T>(result: &Result<T, sqlx::Error>) -> bool {
    matches!(
        result,
        Err(sqlx::Error::Database(error)) if error.code().as_deref() == Some("42501")
    )
}

#[tokio::test]
#[ignore = "needs FORGE_TEST_DATABASE_URL"]
async fn postgres_round_trip_locking_and_pages() -> TestResult {
    let database = RlsTestDatabase::create([&MIGRATOR]).await?;
    exercise(database.runtime()).await?;
    database.cleanup().await?;
    Ok(())
}

/// The runtime role holds data privileges only: whatever an attacker makes
/// the application run, it cannot create, change, empty or drop a
/// table.
#[tokio::test]
#[ignore = "needs FORGE_TEST_DATABASE_URL"]
async fn postgres_runtime_role_cannot_change_the_schema() -> TestResult {
    let database = RlsTestDatabase::create([&MIGRATOR]).await?;
    for statement in [
        r#"CREATE TABLE "intruders" ("id" uuid)"#,
        r#"CREATE TEMPORARY TABLE "scratch" ("id" uuid)"#,
        r#"ALTER TABLE "posts" ADD COLUMN "intruder" text"#,
        r#"TRUNCATE "posts""#,
        r#"DROP TABLE "posts""#,
    ] {
        let refused = sqlx::query(statement)
            .execute(database.runtime().pool())
            .await;
        assert!(
            insufficient_privilege(&refused),
            "the runtime role ran {statement}: {refused:?}"
        );
    }
    database.cleanup().await?;
    Ok(())
}
